#!/usr/bin/env python3
import csv
import json
import os
from pathlib import Path
from collections import defaultdict

# Configuration
QUARTERS = {
    "2025-q2": {
        "coverpage": Path("/root/2025-q2/COVERPAGE.tsv"),
        "infotable": Path("/root/2025-q2/INFOTABLE.tsv"),
    },
    "2025-q3": {
        "coverpage": Path("/root/2025-q3/COVERPAGE.tsv"),
        "infotable": Path("/root/2025-q3/INFOTABLE.tsv"),
    },
}
TARGET_NAME = "bridgewater associates"

def read_tsv(path):
    with open(path, "r", newline="") as f:
        return list(csv.DictReader(f, delimiter="\t"))

def find_best_manager(cover_rows):
    # Simple case-insensitive substring match, take first match
    matches = []
    for row in cover_rows:
        name = row.get("FILINGMANAGER_NAME", "").lower()
        if TARGET_NAME in name:
            matches.append(row)
    if not matches:
        return None
    # If multiple, pick the one with shortest Levenshtein distance to target (approx)
    # For simplicity, return the first.
    return matches[0]

def load_holdings(infotable_path, accession):
    rows = []
    with open(infotable_path, "r", newline="") as f:
        reader = csv.DictReader(f, delimiter="\t")
        for row in reader:
            if row.get("ACCESSION_NUMBER") == accession:
                rows.append(row)
    return rows

def filter_stock_like(rows):
    filtered = []
    for r in rows:
        if r.get("SSHPRNAMTTYPE") == "SH" and (r.get("PUTCALL") or "").strip() == "":
            filtered.append(r)
    return filtered

def aggregate_by_cusip(rows):
    agg = defaultdict(float)
    for r in rows:
        cusip = r.get("CUSIP")
        try:
            value = float(r.get("VALUE", "0").replace(",", ""))
        except ValueError:
            value = 0.0
        agg[cusip] += value
    return dict(agg)

def main():
    quarter_data = {}
    for q, paths in QUARTERS.items():
        cover = read_tsv(paths["coverpage"])
        manager_row = find_best_manager(cover)
        if not manager_row:
            raise RuntimeError(f"No manager matching {TARGET_NAME} in {q}")
        accession = manager_row.get("ACCESSION_NUMBER")
        holdings = load_holdings(paths["infotable"], accession)
        stock = filter_stock_like(holdings)
        agg = aggregate_by_cusip(stock)
        quarter_data[q] = {"accession_number": accession, "aggregated": agg}

    # Compute changes
    q2 = quarter_data["2025-q2"]["aggregated"]
    q3 = quarter_data["2025-q3"]["aggregated"]
    all_cusips = set(q2) | set(q3)
    changes = {}
    for cusip in all_cusips:
        val2 = q2.get(cusip, 0.0)
        val3 = q3.get(cusip, 0.0)
        changes[cusip] = val3 - val2

    # Top 4 increased
    increased = sorted(((c, d) for c, d in changes.items() if d > 0), key=lambda x: x[1], reverse=True)[:4]
    top4_increased = [{"cusip": c, "value_change": d} for c, d in increased]
    # Top 3 decreased (most negative first)
    decreased = sorted(((c, d) for c, d in changes.items() if d < 0), key=lambda x: x[1])[:3]
    top3_decreased = [{"cusip": c, "value_change": d} for c, d in decreased]
    # New positions in Q3 (present in Q3, absent in Q2)
    new_positions = [(c, d) for c, d in changes.items() if c not in q2 and d > 0]
    new_top2 = sorted(new_positions, key=lambda x: x[1], reverse=True)[:2]
    new_positions_top2 = [{"cusip": c, "value_change": d} for c, d in new_top2]

    output = {
        "2025-q2": {"accession_number": quarter_data["2025-q2"]["accession_number"]},
        "2025-q3": {"accession_number": quarter_data["2025-q3"]["accession_number"]},
        "top4_increased_cusips": top4_increased,
        "top3_decreased_cusips": top3_decreased,
        "new_positions_top2": new_positions_top2,
    }
    with open("/root/answers.json", "w") as out:
        json.dump(output, out, indent=2)

if __name__ == "__main__":
    main()

